#ifndef ZONOTOPE_H
#define ZONOTOPE_H

// N_STATE/N_INPUT/N_MEAS/MAX_GEN/REDUCTION_BUDGET/RANDOM_SEED/DT/noise radii
// and the derived TOPK/STEP_MEAS_MAX_GEN/REDUCE_INPUT_MAX_GEN come from the
// single-source config: config/zonotope_params.json -> (generated by
// tools/gen_zonotope_params.py) -> include/zonotope_params.hpp.
// Edit the JSON, not this file, to change dimensions/budgets.
#include "zonotope_params.hpp"

#ifndef NUM_STEPS
#define NUM_STEPS             200   // 仿真步数 // Number of simulation steps
#endif
#define N_BATCH               NUM_STEPS  // Steps per single FPGA kernel call (batch mode)
// #include <ap_fixed.h>
// using data_t = ap_fixed<32, 8>;  // 例子：总32位，整数8位（含符号）
using data_t = float;  // double/float 都行，HLS工具会根据实际情况优化


struct Zonotope {
    int n;          // state dimension 状态维度
    int m;          // number of generators 生成器数量
    data_t p[N_STATE];  // center 中心向量
    data_t H[N_STATE][MAX_GEN]; // generator matrix 生成器矩阵
};

#define HLS_LAMBDA_METHOD_FIXED_GAIN 0
#define HLS_LAMBDA_METHOD_SEGMENT  1
#define HLS_LAMBDA_METHOD_VOLUME   2
#define HLS_LAMBDA_METHOD_P_RADIUS 3

enum LambdaMethod {
    LAMBDA_FIXED_GAIN = HLS_LAMBDA_METHOD_FIXED_GAIN,
    LAMBDA_SEGMENT = HLS_LAMBDA_METHOD_SEGMENT,
    LAMBDA_VOLUME = HLS_LAMBDA_METHOD_VOLUME,
    LAMBDA_P_RADIUS = HLS_LAMBDA_METHOD_P_RADIUS
};

#ifndef HLS_LAMBDA_METHOD_ID
#define HLS_LAMBDA_METHOD_ID HLS_LAMBDA_METHOD_SEGMENT
#endif

#if HLS_LAMBDA_METHOD_ID == HLS_LAMBDA_METHOD_FIXED_GAIN
#define HLS_LAMBDA_METHOD_NAME "Fixed-gain"
#elif HLS_LAMBDA_METHOD_ID == HLS_LAMBDA_METHOD_SEGMENT
#define HLS_LAMBDA_METHOD_NAME "LAMBDA_SEGMENT"
#elif HLS_LAMBDA_METHOD_ID == HLS_LAMBDA_METHOD_VOLUME
#define HLS_LAMBDA_METHOD_NAME "LAMBDA_VOLUME"
#elif HLS_LAMBDA_METHOD_ID == HLS_LAMBDA_METHOD_P_RADIUS
#define HLS_LAMBDA_METHOD_NAME "LAMBDA_P_RADIUS"
#else
#error "Unsupported HLS_LAMBDA_METHOD_ID"
#endif

void compute_lambda_segment(
    data_t lambda[N_STATE],
    const data_t H[N_STATE][MAX_GEN], int m,
    const data_t c[N_STATE],
    data_t phi
);

void compute_lambda_volume(
    data_t lambda[N_STATE],
    const data_t H[N_STATE][MAX_GEN], int m,
    const data_t c[N_STATE],
    data_t phi
);

void compute_lambda_p_radius(
    data_t lambda[N_STATE],
    const data_t H[N_STATE][MAX_GEN], int m,
    const data_t c[N_STATE],
    data_t phi
);

// Reduce H in-place to REDUCTION_BUDGET generators (uses TOPK+N_STATE layout).
// Always reduces to REDUCTION_BUDGET columns; *m is set to REDUCTION_BUDGET.
void zonotope_reduce(data_t H[N_STATE][MAX_GEN], int* m);

#endif
